package com.nigson.commerce.fulfillment;
import java.util.*;
import java.time.*;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.transaction.PlatformTransactionManager;
import org.springframework.transaction.support.*;
import com.nigson.commerce.files.FileStorage;
import com.nigson.commerce.platform.*;
import com.nigson.shared.security.PrivateWorkload;
import com.nigson.shared.events.EventCodec;
import com.nigson.shared.problem.*;
/** Label HEAD outside SQL; command acknowledgement, metadata, history and outbox are one local transaction. */
public final class CarrierResultService {
 private record Intent(UUID order,UUID booking,String mode,String snapshotHash){}
 private final JdbcTemplate jdbc;private final JdbcShipmentRepository repository;private final FileStorage storage;private final FulfillmentPolicy policy;private final PlatformStore commands;private final AuditWriter audit;private final Clock clock;private final String environment;private final TransactionTemplate read;private final io.micrometer.core.instrument.MeterRegistry metrics;
 public CarrierResultService(JdbcTemplate jdbc,JdbcShipmentRepository repository,FileStorage storage,FulfillmentPolicy policy,PlatformStore commands,AuditWriter audit,PlatformTransactionManager manager,Clock clock,String environment,io.micrometer.core.instrument.MeterRegistry metrics){if(!Set.of("local","test","dev","qa","stage","prod").contains(environment)||!storage.configured())throw new IllegalArgumentException("CARRIER_PRIVATE_STORAGE_REQUIRED");this.jdbc=jdbc;this.repository=repository;this.storage=storage;this.policy=policy;this.commands=commands;this.audit=audit;this.clock=clock;this.environment=environment;this.metrics=metrics;read=new TransactionTemplate(manager);read.setReadOnly(true);read.setTimeout(3);read.setIsolationLevel(org.springframework.transaction.TransactionDefinition.ISOLATION_REPEATABLE_READ);}
 private String principal(PrivateWorkload.Proof proof){if(proof==null||proof.actor()!=null||!"nigson-integration".equals(proof.client())||proof.subject()==null||!proof.subject().matches("[A-Za-z0-9._:-]{1,100}")||!PrivateWorkload.ROUTES.stream().anyMatch(r->r.api().equals("API-120")&&r.equals(proof.route())))throw new Problem.Failure(ProblemCode.ACCESS_DENIED);return proof.client();}
 private Intent intent(UUID id,boolean lock){UUID orderId=repository.orderId(id);var order=repository.order(orderId,lock);var row=jdbc.queryForMap("SELECT provider,booking_request_id,package_snapshot::text FROM commerce.shipment WHERE id=?"+(lock?" FOR UPDATE":""),id);if(!"FEDEX".equals(row.get("provider"))||row.get("booking_request_id")==null||!"NGN".equals(order.get("currency_code")))throw FulfillmentValues.rule();var snapshot=EventCodec.JSON.readTree(row.get("package_snapshot").toString());String mode=snapshot.path("mode").asString();var frozen=EventCodec.JSON.readTree(order.get("carrier_snapshot").toString());if(!mode.equals(frozen.path("mode").asString())||!snapshot.path("bookingReference").asString().equals(row.get("booking_request_id").toString()))throw FulfillmentValues.rule();policy.require(mode,"FEDEX");return new Intent(orderId,(UUID)row.get("booking_request_id"),mode,EventCodec.hash(snapshot));}
 public FulfillmentValues.Shipment accept(PrivateWorkload.Proof proof,UUID id,CarrierResultValues.Result input,UUID correlation){String subject=principal(proof);ApiValues.uuid(id==null?null:id.toString());ApiValues.uuid(correlation==null?null:correlation.toString());if(TransactionSynchronizationManager.isActualTransactionActive())throw new IllegalStateException("PROVIDER_CALL_INSIDE_TRANSACTION");if(input.occurredAt().isAfter(clock.instant().plusSeconds(5)))throw ApiValues.invalid();policy.require(input.mode(),"FEDEX");var body=EventCodec.JSON.valueToTree(Map.of("shipment",id,"result",input));String key=input.commandId().toString();
  if(commands.completed(subject,"API-120",key))return decode(commands.executeLocal(subject,"API-120",key,body,db->{throw new IllegalStateException("CARRIER_ACKNOWLEDGEMENT_MISSING");}));
  Intent captured=read.execute(status->intent(id,false));if(!captured.mode().equals(input.mode()))throw new Problem.Failure(ProblemCode.PROVIDER_MODE_MISMATCH);policy.tracking(input.trackingUrl());FileStorage.ObjectInfo label=null;
  if("BOOKED".equals(input.bookingState())){if(!input.labelObjectKey().matches(java.util.regex.Pattern.quote(environment+"/commerce/shipping_label/"+id+"/")+"[0-9]{1,20}/pdf"))throw FulfillmentValues.rule();try{label=storage.finalObject(input.labelObjectKey(),true);}catch(Problem.Failure failure){if(failure.code==ProblemCode.FILES_RULE_VIOLATION)throw FulfillmentValues.rule();throw failure;}if(label==null||!label.encrypted()||label.size()<1||label.size()>10485760||!"application/pdf".equals(label.mimeType())||!input.labelChecksum().equals(label.checksum())||!captured.booking().toString().equals(label.owner()))throw FulfillmentValues.rule();}
  FileStorage.ObjectInfo verified=label;return decode(commands.executeLocal(subject,"API-120",key,body,db->apply(id,input,correlation,captured,verified,subject)));
 }
 private PlatformStore.Response apply(UUID id,CarrierResultValues.Result input,UUID correlation,Intent captured,FileStorage.ObjectInfo label,String subject){
  Intent current=intent(id,true);if(!current.equals(captured))throw FulfillmentValues.rule();var before=repository.find(id,false);if(before.version()==Long.MAX_VALUE)throw FulfillmentValues.rule();String known=jdbc.queryForObject("SELECT provider_reference FROM commerce.shipment WHERE id=?",String.class,id);boolean uncertain=Set.of("UNKNOWN","FAILED").contains(Objects.requireNonNullElse(input.bookingState(),""));if(uncertain){if(!input.reference().equals(current.booking().toString()))throw FulfillmentValues.rule();}else if(known!=null&&!known.equals(input.reference()))throw FulfillmentValues.rule();
  var latest=jdbc.queryForObject("SELECT max(occurred_at) FROM commerce.shipment_event WHERE shipment_id=? AND source='FEDEX' AND status IN ('BOOKED','SHIPPED','DELIVERED','CANCELLED','EXCEPTION')",java.sql.Timestamp.class,id);boolean older=latest!=null&&input.occurredAt().isBefore(latest.toInstant());boolean booked=known!=null&&Boolean.TRUE.equals(jdbc.queryForObject("SELECT EXISTS(SELECT 1 FROM commerce.shipment_event WHERE shipment_id=? AND source='FEDEX' AND status='BOOKED')",Boolean.class,id));String next=CarrierResultStates.next(before.status(),input,older,booked);UUID asset=null;
  if(label!=null){var existing=jdbc.queryForList("SELECT id,shipment_id,purpose,classification,status,checksum_sha256,mime_type,byte_size FROM commerce.asset_reference WHERE object_key=? FOR UPDATE",input.labelObjectKey());if(existing.isEmpty()){asset=EventCodec.uuid7(clock.instant());jdbc.update("INSERT INTO commerce.asset_reference(id,created_by,updated_by,object_key,purpose,mime_type,byte_size,checksum_sha256,status,classification,shipment_id) VALUES (?,?,?,?,'SHIPPING_LABEL','application/pdf',?,?,'CLEAN','PRIVATE',?)",asset,subject,subject,input.labelObjectKey(),label.size(),input.labelChecksum(),id);}else{var stored=existing.getFirst();if(!id.equals(stored.get("shipment_id"))||!"SHIPPING_LABEL".equals(stored.get("purpose"))||!"PRIVATE".equals(stored.get("classification"))||!"CLEAN".equals(stored.get("status"))||!input.labelChecksum().equals(stored.get("checksum_sha256"))||!"application/pdf".equals(stored.get("mime_type"))||((Number)stored.get("byte_size")).longValue()!=label.size())throw FulfillmentValues.rule();asset=(UUID)stored.get("id");}}
  if(next.equals("DELIVERED")&&!before.status().equals("DELIVERED"))repository.delivered(id,before.version(),new FulfillmentValues.Delivery(input.occurredAt(),"Verified carrier delivery evidence"),subject);
  else if(!next.equals(before.status())||!older&&input.trackingUrl()!=null&&!Objects.equals(before.trackingUrl(),input.trackingUrl())||asset!=null){jdbc.update("UPDATE commerce.shipment SET status=?,provider_reference=CASE WHEN ? THEN ? ELSE provider_reference END,label_asset_id=coalesce(?,label_asset_id),tracking_url=CASE WHEN ? THEN coalesce(?,tracking_url) ELSE tracking_url END,version=version+1,updated_at=?,updated_by=? WHERE id=?",next,label!=null,input.reference(),asset,!older,input.trackingUrl(),java.sql.Timestamp.from(clock.instant()),subject,id);}
  String eventStatus=input.bookingState()==null?input.status():input.bookingState();jdbc.update("INSERT INTO commerce.shipment_event(id,created_by,shipment_id,source,event_key,status,occurred_at) VALUES (?,?,?,'FEDEX',?,?,?)",EventCodec.uuid7(clock.instant()),subject,id,input.commandId().toString(),eventStatus,java.sql.Timestamp.from(input.occurredAt()));repository.progress(current.order(),subject);var after=repository.find(id,false);
  audit.append(subject,AuditValues.ActorKind.SERVICE,AuditValues.Action.SHIPMENT_PROVIDER_RESULT,AuditValues.Resource.SHIPMENT,id,correlation,AuditValues.Reason.VERIFIED_PROVIDER,Map.of("state",before.status(),"version",before.version()),Map.of("state",after.status(),"version",after.version()),null);
  if(after.version()!=before.version()){var event=new LinkedHashMap<String,Object>();event.put("event_id",EventCodec.uuid7(clock.instant()));event.put("event_type","shipment.changed.v1");event.put("schema_version",1);event.put("producer","commerce");event.put("occurred_at",clock.instant());event.put("aggregate_id",id);event.put("aggregate_version",after.version());event.put("organization_id",repository.organization(current.order()));event.put("correlation_id",correlation);event.put("traceparent",null);event.put("payload",Map.of("shipment_id",id,"order_id",current.order(),"status",after.status(),"occurred_at",input.occurredAt()));commands.append(EventCodec.JSON.writeValueAsString(event),subject);}
  TransactionSynchronizationManager.registerSynchronization(new TransactionSynchronization(){public void afterCommit(){metrics.counter("nigson.fulfillment.provider-results","status",eventStatus).increment();}});return new PlatformStore.Response(200,EventCodec.JSON.valueToTree(after),id);
 }
 private FulfillmentValues.Shipment decode(PlatformStore.Response response){return EventCodec.JSON.treeToValue(response.body(),FulfillmentValues.Shipment.class);}
}
